export function init({q}){
  const cats=[
    ['01','Shoes','Sneakers, slides, trainers and casual pairs.','https://findspreadsheet.com/shoes/'],['02','Hoodies / Sweaters','Sweatshirts, hoodies and layered essentials.','https://findspreadsheet.com/hoodies-sweaters/'],['03','T-Shirts','T-shirts, polos and everyday tops.','https://findspreadsheet.com/t-shirts/'],['04','Jackets','Outerwear, puffers and light layers.','https://findspreadsheet.com/jackets/'],['05','Pants / Shorts','Trousers, denim and short sets.','https://findspreadsheet.com/pants-shorts/'],['06','Headwear','Caps, hats and daily headwear.','https://findspreadsheet.com/headwear/'],['07','Accessories','Small goods and finishing pieces.','https://findspreadsheet.com/accessories/'],['08','Jersey','Football and sports jersey finds.','https://findspreadsheet.com/jersey/'],['09','Electronics','Audio and useful technology.','https://findspreadsheet.com/electronics/'],['10','Other Stuff','The wider FindSpreadsheet selection.','https://findspreadsheet.com/other-stuff/']
  ];
  const style=document.createElement('style');style.textContent=`
  :root{--paper:#000;--ink:#F6F2F8;--muted:#BDB4C4;--line:rgba(216,213,226,.34);--purple:#A855F7;--violet:#8A2BE2;--panel:#16111c}body{background:#000;color:#F6F2F8}.shell{max-width:1500px;padding:0 42px}.topline{display:none}.nav{position:sticky;top:0;z-index:30;padding:19px 0;background:rgba(0,0,0,.93);backdrop-filter:blur(16px);border-color:var(--line)}.brand{color:#fff;font-size:20px}.navlinks{gap:22px;font-size:12px;color:#eae3ef}.navlinks a:hover,.navlinks a[aria-current=page]{color:#c98cff}.navtools{gap:8px}.lang{background:transparent;color:#fff;border-color:var(--line);border-radius:3px}.database{border-radius:3px;background:#8A2BE2;box-shadow:none}.database:hover{background:#A855F7}.muse-hero{display:grid;grid-template-columns:1.25fr .7fr .72fr;min-height:470px;border-bottom:1px solid var(--line)}.muse-hero>div{padding:54px 30px;border-right:1px solid var(--line)}.muse-hero>div:first-child{padding-left:0}.muse-hero>div:last-child{border:0;padding-right:0}.muse-kicker,.muse-no{font:11px 'DM Mono',monospace;letter-spacing:.1em;color:#cb9bff}.muse-title{font:800 clamp(4.2rem,8.3vw,9.2rem)/.76 Manrope,Arial,sans-serif;letter-spacing:-.11em;margin:25px 0 31px;color:#fff}.muse-title em{font-family:Georgia,serif;font-style:italic;font-weight:400;color:#c98cff}.muse-search{display:flex;max-width:510px;border-bottom:1px solid #D8D5E2}.muse-search input{flex:1;min-width:0;color:#fff;background:transparent;border:0;padding:14px 3px;outline:0}.muse-search input::placeholder{color:#BDB4C4}.muse-search button{background:transparent;color:#fff;border:0;font-size:12px;font-weight:900;cursor:pointer}.muse-statement{display:flex;flex-direction:column;justify-content:space-between}.muse-statement p{font:700 25px/1.13 Manrope,Arial,sans-serif;letter-spacing:-.055em;margin:0}.muse-statement small{color:#BDB4C4;font-size:12px}.muse-route{display:flex;flex-direction:column;justify-content:space-between;background:#8A2BE2;color:white;transition:background .18s}.muse-route:hover{background:#A855F7}.muse-route strong{font:800 32px/1.02 Manrope,Arial,sans-serif;letter-spacing:-.065em}.muse-route span{font:12px 'DM Mono',monospace}.muse-collections{display:grid;grid-template-columns:.82fr 1.18fr;gap:56px;padding:70px 0 80px}.collection-intro{position:sticky;top:96px;align-self:start}.collection-intro h2{font:800 55px/.9 Manrope,Arial,sans-serif;letter-spacing:-.09em;margin:16px 0}.collection-intro p{color:#BDB4C4;max-width:270px;font-size:14px}.muse-preview{height:210px;margin-top:35px;border:1px solid var(--line);display:flex;flex-direction:column;justify-content:flex-end;padding:18px;background:radial-gradient(circle at 75% 20%,rgba(168,85,247,.68),transparent 22%),linear-gradient(135deg,#241537 0 49%,#17111e 49%);transition:background .2s}.muse-preview b{font:800 42px/.85 Manrope,Arial,sans-serif;letter-spacing:-.08em}.muse-preview span{font:11px 'DM Mono',monospace;color:#dfc5ff;margin-top:9px}.collection-list{border-top:1px solid var(--line)}.collection-row{width:100%;border:0;border-bottom:1px solid var(--line);background:transparent;color:#fff;padding:19px 0;display:grid;grid-template-columns:50px 1fr 160px 30px;align-items:center;gap:16px;text-align:left;cursor:pointer;transition:padding .2s}.collection-row:hover,.collection-row:focus-visible{padding-left:13px;outline:0;background:linear-gradient(90deg,rgba(138,43,226,.23),transparent 72%)}.collection-row:hover .row-title{color:#d59fff}.row-title{font:800 clamp(1.65rem,3vw,3rem)/1 Manrope,Arial,sans-serif;letter-spacing:-.075em}.row-description{font-size:12px;line-height:1.35;color:#BDB4C4}.row-arrow{font-size:25px;text-align:right;color:#c98cff}.muse-footer-grid{border-top:1px solid var(--line);display:grid;grid-template-columns:1.2fr 1fr 1fr}.muse-footer-grid>a{min-height:205px;padding:29px;border-right:1px solid var(--line);display:flex;flex-direction:column;justify-content:space-between;color:#fff}.muse-footer-grid>a:last-child{border:0}.muse-footer-grid h3{font:800 27px/1 Manrope,Arial,sans-serif;letter-spacing:-.06em;margin:0}.muse-footer-grid p{font-size:13px;color:#BDB4C4;margin:12px 0}.muse-footer-grid .route-card{background:#16111c;color:#fff}.muse-footer-grid .route-card p{color:#BDB4C4}.muse-drawer{position:fixed;top:0;right:0;z-index:50;width:min(470px,100%);height:100dvh;background:#000;color:#fff;padding:34px;box-shadow:-22px 0 60px rgba(0,0,0,.7);transform:translateX(104%);transition:transform .27s}.muse-drawer.open{transform:translateX(0)}.muse-close{position:absolute;right:19px;top:15px;border:0;background:none;color:#fff;font-size:26px;cursor:pointer}.drawer-visual{height:250px;background:linear-gradient(135deg,#000 0 49%,#8A2BE2 49% 65%,#16111c 65%);margin:25px 0;display:flex;align-items:end;padding:18px;color:#fff;font:11px 'DM Mono',monospace;letter-spacing:.1em}.muse-drawer h2{font:800 58px/.85 Manrope,Arial,sans-serif;letter-spacing:-.1em;margin:0 0 14px}.muse-drawer p{max-width:330px;color:#BDB4C4}.muse-drawer a{display:inline-block;margin-top:18px;background:#8A2BE2;color:#fff;padding:13px 16px;font-size:12px;font-weight:900}.page-hero,.section{border-color:var(--line)}.page-title,.section h2,.article h2{color:#fff}.page-lead,.article p,.section-head p,.faq p{color:#BDB4C4}.card,.feature{background:#16111c;border:1px solid var(--line);color:#fff}.card p,.feature p{color:#BDB4C4}.faq summary{color:#fff}.footer{color:#fff;border-color:var(--line)}@media(max-width:860px){.shell{padding:0 18px}.navlinks{display:none}.muse-hero{grid-template-columns:1fr}.muse-hero>div,.muse-hero>div:first-child,.muse-hero>div:last-child{padding:35px 0;border-right:0;border-bottom:1px solid var(--line)}.muse-title{font-size:4.5rem}.muse-statement{min-height:150px}.muse-route{padding:28px!important}.muse-collections{grid-template-columns:1fr;gap:30px;padding:42px 0}.collection-intro{position:static}.muse-preview{height:150px;margin-top:20px}.collection-row{grid-template-columns:37px 1fr 25px}.row-description{display:none}.muse-footer-grid{grid-template-columns:1fr}.muse-footer-grid>a{border-right:0;border-bottom:1px solid var(--line);min-height:155px}.muse-footer-grid>a:last-child{border:0}.footer{display:none}}
  /* Desktop inner stage: outer hero remains fixed; only the content sits in the centered yellow-frame proportion. */
  @media(min-width:861px){.muse-hero{box-sizing:border-box;height:580px;min-height:580px;padding:84px 54px 92px}.muse-hero>div{padding:25px 20px}.muse-hero>div:first-child{padding-left:20px}.muse-title{font-size:clamp(3.7rem,5vw,5.6rem);margin:10px 0 14px}.muse-search input{padding:9px 3px}.muse-statement p{font-size:21px;line-height:1.08}.muse-route{padding:25px 20px}.muse-route strong{font-size:26px}}
  /* Compact the independent-page heading band; the homepage stage deliberately keeps its existing frame and size. */
  .page-hero{min-height:0;padding:24px 0 20px}.page-hero.research-hero{padding:24px 0 20px}.page-hero .page-title{max-width:1180px;margin:8px 0 12px;font-size:clamp(2.35rem,4vw,4.25rem);line-height:.94}.page-hero .page-lead{max-width:980px;margin:0;font-size:15px;line-height:1.45}
  @media(max-width:860px){.page-hero,.page-hero.research-hero{padding:20px 0 16px}.page-hero .page-title{max-width:100%;margin:7px 0 10px;font-size:clamp(2rem,8vw,2.7rem);line-height:.98}.page-hero .page-lead{font-size:14px;line-height:1.45}}
  `;document.head.append(style);
  if((location.pathname.replace(/\/$/,'')||'/')!=='/')return;
  const main=q('main');if(!main)return;
  main.innerHTML=`<section class="muse-hero"><div><span class="muse-kicker">LITBUYY / PRODUCT INDEX / 2026</span><h1 class="muse-title">FIND<br><em>THE</em><br>EDIT.</h1><form class="muse-search" id="muse-search"><input id="muse-query" placeholder="Search the main database"><button>SEARCH →</button></form></div><div class="muse-statement"><span class="muse-kicker">EDITOR’S PRINCIPLE</span><p>Less noise.<br>Better routes.<br>One clear selection at a time.</p><small>Browse · compare · continue</small></div><a class="muse-route" href="https://findspreadsheet.com"><span>DIRECT ROUTE / 01</span><strong>ENTER<br>THE MAIN<br>DATABASE →</strong><span>findspreadsheet.com</span></a></section><section class="muse-collections"><aside class="collection-intro"><span class="muse-kicker">THE TEN COLLECTIONS</span><h2>Choose a direction, not a distraction.</h2><p>Each collection opens a concise detail drawer before sending you to the matching FindSpreadsheet selection.</p><div class="muse-preview" id="muse-preview"><b>SHOES</b><span>01 / FOOTWEAR FOR A DAILY ROTATION</span></div></aside><div class="collection-list">${cats.map((c,i)=>`<button class="collection-row" data-c="${i}"><span class="muse-no">${c[0]}</span><span class="row-title">${c[1]}</span><span class="row-description">${c[2]}</span><span class="row-arrow">↗</span></button>`).join('')}</div></section><section class="muse-footer-grid"><a class="route-card" href="https://findspreadsheet.com"><span class="muse-kicker">MAIN DATABASE</span><div><h3>Search the full product index.</h3><p>Move directly to the main selection when you already know what you need.</p></div><span>OPEN DATABASE →</span></a><a href="/products/"><span class="muse-kicker">PRODUCT DETAILS</span><div><h3>Use a calm checking routine.</h3><p>Read measurements, product information and practical details separately.</p></div><span>OPEN GUIDE →</span></a><a href="/faq/"><span class="muse-kicker">COMMON QUESTIONS</span><div><h3>Short answers, clearly given.</h3><p>Practical information about browsing, product details and search.</p></div><span>OPEN FAQ →</span></a></section><aside class="muse-drawer" aria-hidden="true"><button class="muse-close" aria-label="Close">×</button><span class="muse-kicker">COLLECTION DETAIL</span><div class="drawer-visual" id="drawer-visual">01 / PRODUCT DIRECTION</div><h2 id="drawer-name">Shoes</h2><p id="drawer-copy">Footwear for a daily rotation.</p><a id="drawer-route" href="https://findspreadsheet.com">OPEN THIS SELECTION →</a></aside>`;
  q('#muse-search').addEventListener('submit',e=>{e.preventDefault();const term=q('#muse-query').value.trim();if(term)location.href='https://findspreadsheet.com/search?q='+encodeURIComponent(term)});
  const drawer=q('.muse-drawer'),set=i=>{const c=cats[i];q('#muse-preview').innerHTML=`<b>${c[1].toUpperCase()}</b><span>${c[0]} / ${c[2].toUpperCase()}</span>`;q('#drawer-visual').textContent=`${c[0]} / ${c[1].toUpperCase()} / PRODUCT DIRECTION`;q('#drawer-name').textContent=c[1];q('#drawer-copy').textContent=c[2];q('#drawer-route').href=c[3]};document.querySelectorAll('.collection-row').forEach(row=>{const i=Number(row.dataset.c);row.addEventListener('mouseenter',()=>set(i));row.addEventListener('focus',()=>set(i));row.addEventListener('click',()=>{set(i);drawer.classList.add('open');drawer.setAttribute('aria-hidden','false')})});q('.muse-close').onclick=()=>{drawer.classList.remove('open');drawer.setAttribute('aria-hidden','true')};
}
